def img(f,a,w=600):return f'<img src="assets/{f}" width="{w}" alt="{escape(a)}" style="display:block;border:0;width:100%;max-width:{w}px;height:auto;">'
def pic(f,a,u,w=600):return f'<a href="{u}" target="_blank" style="text-decoration:none;">{img(f,a,w)}</a>'
def label(t,c=M):return f'<p style="margin:0 0 10px;color:{c};font:700 10px/16px Arial,sans-serif;letter-spacing:1.6px;">{t}</p>'
def h(t,n=30,c=INK):return f'<h2 class="headline" style="margin:0 0 14px;color:{c};text-align:center;text-transform:uppercase;font:700 {n}px/{n+4}px Arial Narrow,Arial,sans-serif;letter-spacing:-.7px;">{t}</h2>'
def p(t,c=INK):return f'<p style="margin:0 0 18px;color:{c};font:15px/23px Arial,sans-serif;">{t}</p>'
def link(t,u):return f'<a href="{u}" target="_blank" style="display:inline-block;padding:7px 0;color:{M};font:700 13px/20px Arial,sans-serif;text-decoration:underline;">{t} &rarr;</a>'
def cta(t,u,light=False):
 bg='#ffffff' if light else M;fg=M if light else '#ffffff'
 return f'<table role="presentation" align="center" cellpadding="0" cellspacing="0"><tr><td bgcolor="{bg}" style="background:{bg};border-radius:26px;mso-padding-alt:13px 19px;"><a href="{u}" target="_blank" style="display:inline-block;padding:13px 19px;border:1px solid {bg};border-radius:26px;color:{fg};font:700 12px/20px Arial,sans-serif;text-decoration:none;mso-padding-alt:0;">{t} &nbsp; &rarr;</a></td></tr></table>'
def row(t,pad='0 24px 20px',bg=PAPER):return f'<tr><td class="outer" bgcolor="{bg}" style="background:{bg};padding:{pad};">{t}</td></tr>'
def card(t,bg=PAPER,pad='26px',extra=''):return f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:{bg};border:0;border-radius:0;{extra}"><tr><td class="inner" bgcolor="{bg}" style="padding:{pad};border-radius:0;">{t}</td></tr></table>'
def section(k,t):return row('<div style="text-align:center;padding:16px 0 5px;">'+'<table role="presentation" align="center" width="70" style="margin-bottom:18px;"><tr><td style="border-top:1px solid #500000;height:1px;font-size:1px;">&nbsp;</td></tr></table>'+label(k)+h(t,26)+'</div>',pad='8px 24px 0')
